// Exports the compiled Sotto contract. contract/managed/sotto is generated by
// `npm run compile` (gitignored).
import { CompiledContract } from '@midnight-ntwrk/midnight-js-protocol/v9/compact-js';
import path from 'node:path';

export {
  Contract,
  ledger,
  pureCircuits,
  CaseStatus,
  type Witnesses,
  type Ledger,
  type ImpureCircuits,
  type PureCircuits,
} from './managed/sotto/contract/index.js';
import { Contract } from './managed/sotto/contract/index.js';
import { witnesses } from './witnesses.js';

const currentDir = path.resolve(new URL(import.meta.url).pathname, '..');
export const zkConfigPath = path.resolve(currentDir, 'managed', 'sotto');

export const CompiledSottoContract = CompiledContract.make('SottoContract', Contract).pipe(
  CompiledContract.withWitnesses(witnesses),
  CompiledContract.withCompiledFileAssets(zkConfigPath),
);
